// Writes the compiled ABI into the web app so it builds without compiling contracts.
import { readFileSync, writeFileSync, mkdirSync } from "node:fs";
import { fileURLToPath } from "node:url";

const artifact = JSON.parse(
  readFileSync(new URL("../artifacts/contracts/TicketLockDemo.sol/TicketLockDemo.json", import.meta.url), "utf8"),
);
const outDir = fileURLToPath(new URL("../../web/src/lib/contract/", import.meta.url));
mkdirSync(outDir, { recursive: true });
writeFileSync(
  outDir + "abi.ts",
  "// Generated by contracts/scripts/export-abi.mjs. Do not edit by hand.\n" +
    "export const ticketLockAbi = " + JSON.stringify(artifact.abi, null, 2) + " as const;\n",
);
console.log("ABI exported:", artifact.abi.length, "entries");
